/* Lightweight HTML sanitizer - strips dangerous tags/attrs, keeps safe markdown output */
var DOMPurify = (function() {
  var SAFE_TAGS = ['p','br','hr','h1','h2','h3','h4','h5','h6','strong','em','b','i','u','s','del','ins','sub','sup','mark','small','blockquote','pre','code','ul','ol','li','dl','dt','dd','table','thead','tbody','tfoot','tr','th','td','caption','colgroup','col','a','img','figure','figcaption','span','div','abbr','ruby','rt','rp','details','summary','sup','sub','kbd','var','samp','abbr','cite','dfn','time','wbr','section','article','aside','header','footer','nav','main','address'];
  var SAFE_ATTRS = ['href','src','alt','title','class','id','width','height','colspan','rowspan','scope','align','valign','style','target','rel','loading','poster','controls','autoplay','loop','muted','playsinline','placeholder','srcset','sizes','decoding','crossorigin','loading','lang','dir'];
  var DANGEROUS_TAGS = ['script','iframe','object','embed','form','input','textarea','button','select','link','meta','base','applet','style'];

  function sanitize(html) {
    if (!html || typeof html !== 'string') return '';
    var tmp = document.createElement('div');
    tmp.innerHTML = html;
    cleanNode(tmp);
    return tmp.innerHTML;
  }

  function cleanNode(node) {
    var children = Array.prototype.slice.call(node.childNodes);
    for (var i = 0; i < children.length; i++) {
      var child = children[i];
      if (child.nodeType === 1) {
        var tag = child.tagName.toLowerCase();
        if (DANGEROUS_TAGS.indexOf(tag) !== -1) {
          node.removeChild(child);
          continue;
        }
        var attrs = Array.prototype.slice.call(child.attributes);
        for (var j = 0; j < attrs.length; j++) {
          var name = attrs[j].name.toLowerCase();
          var val = attrs[j].value || '';
          if (name.indexOf('on') === 0 || val.match(/javascript\s*:/i) || val.match(/data\s*:/i) || name === 'formaction') {
            child.removeAttribute(attrs[j].name);
          }
        }
        cleanNode(child);
      }
    }
  }

  return { sanitize: sanitize };
})();
